// Hand-written. Not generated by Speakeasy.
//
// Guards against the destructive-import regression.
//
// organizationId and apiServerId are needed by the IdP to create and delete a
// service, but the cluster read returns a bare `service` and can never return
// them. Modelled as resource attributes they are null in state after
// `terraform import`, and the generator marks them RequiresReplaceIfConfigured
// because they are absent from the update body -- so the first plan after any
// import proposed destroying the authorization server along with every client
// and token underneath it.
//
// The fix removes them from the Terraform surface entirely (see
// x-speakeasy-terraform-ignore in .speakeasy/terraform_overlay.yaml); the
// provider supplies both from provider-level configuration instead.
//
// These tests exist because that fix lives in the overlay, and an overlay edit
// or a generator change could quietly reinstate the attributes. Nothing else
// would notice: the provider would still build, and every test that only
// creates resources would still pass. The failure only appears when a customer
// imports an existing service, which is the first thing every migrating
// customer does.
package provider

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
)

func resourceSchema(t *testing.T, r resource.Resource) schema.Schema {
	t.Helper()
	resp := &resource.SchemaResponse{}
	r.Schema(context.Background(), resource.SchemaRequest{}, resp)
	if resp.Diagnostics.HasError() {
		t.Fatalf("resource schema has errors: %v", resp.Diagnostics)
	}
	return resp.Schema
}

// TestServiceDoesNotModelUnreadableIdentifiers is the direct guard: if either
// attribute reappears, the destructive plan comes back with it.
func TestServiceDoesNotModelUnreadableIdentifiers(t *testing.T) {
	attrs := resourceSchema(t, NewServiceResource()).Attributes

	for _, name := range []string{"organization_id", "api_server_id"} {
		if _, present := attrs[name]; present {
			t.Errorf("authlete_service has an `%s` attribute again.\n\n"+
				"The API can never return this field, so it is null in state after "+
				"`terraform import`, and the generator marks it as forcing replacement. "+
				"That makes the first plan after any import propose destroying the "+
				"service and everything under it.\n\n"+
				"Restore `x-speakeasy-terraform-ignore: true` on "+
				"service_create_idp_request.properties.%s in "+
				".speakeasy/terraform_overlay.yaml.", name, camel(name))
		}
	}
}

// TestNoAttributeForcesReplacement is the broader invariant. Every field that
// forces replacement is a destroy waiting to happen if the API cannot return it,
// and this provider currently has none. A new one is not necessarily wrong, but
// it must be a deliberate decision rather than something a regeneration
// introduced unnoticed.
func TestNoAttributeForcesReplacement(t *testing.T) {
	for name, res := range map[string]resource.Resource{
		"authlete_service": NewServiceResource(),
		"authlete_client":  NewClientResource(),
	} {
		for attrName, attr := range resourceSchema(t, res).Attributes {
			if !forcesReplacement(attr) {
				continue
			}
			t.Errorf("%s.%s forces replacement.\n\n"+
				"If the API cannot return this field, it will be null after "+
				"`terraform import` and the next plan will propose destroying the "+
				"resource. Confirm the API returns it on read; if it does, add it to "+
				"the allow-list in this test with a note explaining why.", name, attrName)
		}
	}
}

// forcesReplacement reports whether an attribute carries a RequiresReplace plan
// modifier, by asking each modifier to describe itself. The framework has no
// exported way to inspect this, and the descriptions are stable across versions.
func forcesReplacement(attr schema.Attribute) bool {
	ctx := context.Background()
	describe := func(d interface{ Description(context.Context) string }) bool {
		return contains(d.Description(ctx), "replace")
	}
	switch a := attr.(type) {
	case schema.Int64Attribute:
		for _, m := range a.PlanModifiers {
			if describe(m) {
				return true
			}
		}
	case schema.StringAttribute:
		for _, m := range a.PlanModifiers {
			if describe(m) {
				return true
			}
		}
	case schema.BoolAttribute:
		for _, m := range a.PlanModifiers {
			if describe(m) {
				return true
			}
		}
	}
	return false
}

func contains(haystack, needle string) bool {
	for i := 0; i+len(needle) <= len(haystack); i++ {
		match := true
		for j := range needle {
			c := haystack[i+j]
			if c >= 'A' && c <= 'Z' {
				c += 'a' - 'A'
			}
			if c != needle[j] {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}

// camel converts snake_case back to the spec's camelCase, so the failure message
// names the exact overlay target to restore.
func camel(s string) string {
	out := make([]byte, 0, len(s))
	up := false
	for i := 0; i < len(s); i++ {
		if s[i] == '_' {
			up = true
			continue
		}
		c := s[i]
		if up && c >= 'a' && c <= 'z' {
			c -= 'a' - 'A'
		}
		up = false
		out = append(out, c)
	}
	return string(out)
}
